local config = {
  ui_story_31780401_1_dialog_content = "Again with the \"What are you doing here?\"...",
  ui_story_31780401_2_dialog_content = "Look at the time! The question is, why are you still sleeping here, Vic!?",
  ui_story_31780401_3_dialog_content = "Have you forgotten what day it is?",
  ui_story_31780401_4_dialog_content = "Huh? What day is it?",
  ui_story_31780401_5_dialog_content = "... I really wish you'd pull yourself together.",
  ui_story_31780401_6_dialog_content = "Today's <color=#FFB400>the day of your showdown</color> with that other <color=#FFB400>extrozoologist</color>!",
  ui_story_31780401_7_dialog_content = "Yikes! Thank you so much, PlayerName.",
  ui_story_31780401_8_dialog_content = "I'm a little hard up right now.",
  ui_story_31780401_9_dialog_content = "If you hadn't stepped up and helped me out, Little Furball would have had to go without meat!",
  ui_story_31780401_10_option_content = "Quid pro quo",
  ui_story_31780401_11_dialog_content = "As long as you remember to keep your promise.",
  ui_story_31780401_12_dialog_content = "After this, if the wondrous beasts on the Colossus start making a racket, you have to deal with them no matter the time of day.",
  ui_story_31780401_13_dialog_content = "Right, I know, I know.",
  ui_story_31780401_14_dialog_content = "I'll do exactly as I promised you. I'm a man of my word.",
  ui_story_31780401_15_option_content = "I did it for Little Furball",
  ui_story_31780401_16_dialog_content = "It's just because Little Furball is so cute. I've always wanted to buy a gift for it.",
  ui_story_31780401_17_dialog_content = "Chirp!",
  ui_story_31780401_18_dialog_content = "Oh! Looks like Little Furball wants to thank you too!",
  ui_story_31780401_19_dialog_content = "You really are such a kind person, PlayerName!",
  ui_story_31780401_20_dialog_content = "...",
  ui_story_31780401_21_dialog_content = "Now, let's head to the next stall. It's time to buy some fresh meat!",
  ui_story_31780401_22_dialog_content = "That's Little Furball's favorite—",
  ui_story_31780401_23_dialog_content = "Freshly sliced meat isn't exactly the ideal food choice for a long-haired weasel.",
  ui_story_31780401_24_dialog_content = "... Huh?",
  ui_story_31780401_25_dialog_content = "Eh?",
  ui_story_31780401_26_dialog_content = "They're considered a predatory species.",
  ui_story_31780401_27_dialog_content = "You should let it hunt by itself and eat fresh prey.",
  ui_story_31780401_28_dialog_content = "Eating freshly sliced meat is not good for their teeth, and being fed like this affects their natural temperament.",
  ui_story_31780401_29_dialog_content = "S-Someone's actually trying to lecture Vic on wondrous beasts?",
  ui_story_31780401_30_dialog_content = "Haha, I'm doing nothing of the sort.",
  ui_story_31780401_31_dialog_content = "But as an extrozoologist, it's only natural that I know a great deal about wondrous beasts.",
  ui_story_31780401_32_dialog_content = "You young people, you're all about appearances and little else. When it comes to wondrous beasts, you must pay closer attention to methods of nurture.",
  ui_story_31780401_33_dialog_content = "I can't help trying to correct your erroneous ways. After all, wondrous beasts are my life.",
  ui_story_31780401_34_dialog_content = "Erm... All about appearances?",
  ui_story_31780401_35_dialog_content = "Chirp, chirp!",
  ui_story_31780401_36_dialog_content = "Wow, Little Furball looks really worked up!",
  ui_story_31780401_37_dialog_content = "...",
  ui_story_31780401_38_dialog_content = "My, my. I rarely meet someone who knows what species Little Furball is.",
  ui_story_31780401_39_dialog_content = "It appears you really know a little something about wondrous beasts.",
  ui_story_31780401_40_dialog_content = "Know \"a little something\" about wondrous beasts?",
  ui_story_31780401_41_dialog_content = "But you don't even know what Little Furball's saying right now, so I think I might know a little more about wondrous beasts than you do.",
  ui_story_31780401_42_dialog_content = "... Young man, if you're going to be arrogant, you should at least be able to back it up.",
  ui_story_31780401_43_dialog_content = "It appears you're not quite convinced of my expertise.",
  ui_story_31780401_44_dialog_content = "Why don't we have a competition?",
  ui_story_31780401_45_dialog_content = "I'm not interested.",
  ui_story_31780401_46_dialog_content = "Haha, don't be so hasty to decline. What happened to all your arrogant bravado?",
  ui_story_31780401_47_dialog_content = "I have two Peko rabbits here. They're fierce, and they love biting people by nature.",
  ui_story_31780401_48_dialog_content = "A Lumopolis noble bought them and asked me to tame them.",
  ui_story_31780401_49_dialog_content = "How about you and I take one each and use our respective methods to train them for ten days?",
  ui_story_31780401_50_dialog_content = "After that, let's see whose Peko is in the best condition and possess the most ideal temperament. What do you think?",
  ui_story_31780401_51_dialog_content = "Peko Rabbits?",
  ui_story_31780401_52_dialog_content = "Wait here. I'll go fetch them.",
  ui_story_31780401_53_dialog_content = "These two, right here.",
  ui_story_31780401_54_dialog_content = "Peko-peko!",
  ui_story_31780401_55_dialog_content = "Their sex, age, and current physical state are the same. I'll let you pick first.",
  ui_story_31780401_56_dialog_content = "How about it? It would be a completely fair competition.",
  ui_story_31780401_57_dialog_content = "<size=30>A Lumopolis noble...?</size>",
  ui_story_31780401_58_dialog_content = "Alright. I'll take this one.",
  ui_story_31780401_59_dialog_content = "Okay, we'll meet here at this time 10 days from now.",
  ui_story_31780401_60_dialog_content = "My name is Stiggan.",
  ui_story_31780401_61_dialog_content = "Oh, I remember now!",
  ui_story_31780401_62_dialog_content = "I guess that really did happen...",
  ui_story_31780401_63_dialog_content = "You finally remember! I thought that flashback was going to last forever!",
  ui_story_31780401_64_dialog_content = "After we got back, I looked that guy Stiggan up.",
  ui_story_31780401_65_dialog_content = "He's apparently a well-known extrozoologist.",
  ui_story_31780401_66_dialog_content = "He even gave several lectures in Lumopolis!",
  ui_story_31780401_67_dialog_content = "That's clearly not someone you should take lightly... Are you really not worried?",
  ui_story_31780401_68_dialog_content = "He couldn't even understand when Little Furball was telling him off! What do I have to be afraid of?",
  ui_story_31780401_69_dialog_content = "It would make more sense for you to ask me why I even wanted to participate in such a farce of a competition in the first place.",
  ui_story_31780401_70_dialog_content = "Huh? Little Furball was telling him off? That's why it sounded so worked up!",
  ui_story_31780401_71_dialog_content = "Correct.",
  ui_story_31780401_72_dialog_content = "What was it saying?",
  ui_story_31780401_73_dialog_content = "\"You know nothing!\"",
  ui_story_31780401_74_dialog_content = "...",
  ui_story_31780401_75_dialog_content = "Anyway, we've already accepted his challenge, we have to keep our word!",
  ui_story_31780401_76_dialog_content = "We're going to be late. Go back to your room and wash your face... and take the Peko with you!",
  ui_story_31780401_77_dialog_content = "Hey, don't push me!",
  ui_story_31780401_78_dialog_content = "Ow, that hurts! My arm—",
  ui_story_31780401_79_dialog_content = "You're late.",
  ui_story_31780401_80_dialog_content = "S-Sorry, something came up.",
  ui_story_31780401_81_dialog_content = "<size=30>Vic, you should apologize.</size>",
  ui_story_31780401_82_dialog_content = "*Yawns* Let's get this over with, I'm sleepy.",
  ui_story_31780401_83_dialog_content = "...",
  ui_story_31780401_84_dialog_content = "...",
  ui_story_31780401_85_dialog_content = "Just from observing your attitude, I already regret wasting my precious time with you.",
  ui_story_31780401_86_dialog_content = "Let's hurry up and compare the Pekos so I can return them to that noble.",
  ui_story_31780401_87_dialog_content = "Peko...",
  ui_story_31780401_88_dialog_content = "Look at this. This Peko no longer resists the touch of Aurorians.",
  ui_story_31780401_89_dialog_content = "No matter where you touch it, you don't have to worry about it biting you.",
  ui_story_31780401_90_dialog_content = "That's true... but it looks like it's lost a bit of its spunk.",
  ui_story_31780401_91_dialog_content = "Ten days is too short after all, so it was very difficult to tame it.",
  ui_story_31780401_92_dialog_content = "It wasn't easy for me to achieve this level of obedience. I had to make full use of my understanding of Peko Rabbit habits.",
  ui_story_31780401_93_dialog_content = "But the other Peko only took two days to completely recover its vitality!",
  ui_story_31780401_94_dialog_content = "It became very amiable and played with all of the Aurorians on the Colossus.",
  ui_story_31780401_95_dialog_content = "Talk is cheap. Let's take a look at it.",
  ui_story_31780401_96_dialog_content = "So, young man, where's your Peko?",
  ui_story_31780401_97_dialog_content = "I let it go.",
  ui_story_31780401_98_dialog_content = "What? You let it go!?",
  ui_story_31780401_99_dialog_content = "Huh? Why!? It's obvious you would have won the bet, Vic!",
  ui_story_31780401_100_dialog_content = "I didn't want to participate in this thing from the beginning.",
  ui_story_31780401_101_dialog_content = "What's the point of beating an old man? There wasn't even any money at stake.",
  ui_story_31780401_102_dialog_content = "...",
  ui_story_31780401_103_dialog_content = "So, you took the Peko so that you could...",
  ui_story_31780401_104_dialog_content = "I know all about those Lumopolis nobles who claim to like wondrous beasts.",
  ui_story_31780401_105_dialog_content = "After all, we used to deal with them all the time.",
  ui_story_31780401_106_dialog_content = "They dispose of their wondrous beasts whenever they become even a slight inconvenience to them.",
  ui_story_31780401_107_dialog_content = "There's no way I could let it go back to that kind of life.",
  ui_story_31780401_108_dialog_content = "You have a point.",
  ui_story_31780401_109_dialog_content = "You do realize that I could report you to the Lumopolis Hall of Justice for what you've done, right?",
  ui_story_31780401_110_dialog_content = "Meh, I really don't care. I can sleep and write absolutely anywhere.",
  ui_story_31780401_111_dialog_content = "But if your noble friend were to find out that you used their \"private property\" to hold a competition without their permission...",
  ui_story_31780401_112_dialog_content = "and that you lost one, while the other one was tamed to a sub-par standard...",
  ui_story_31780401_113_dialog_content = "Well then, I'm afraid both your friendship and your reputation might be in jeopardy.",
  ui_story_31780401_114_dialog_content = "What're you saying?",
  ui_story_31780401_115_dialog_content = "Peko-peko!",
  ui_story_31780401_116_dialog_content = "Peko?",
  ui_story_31780401_117_dialog_content = "Peko.",
  ui_story_31780401_118_dialog_content = "Peko!",
  ui_story_31780401_119_dialog_content = "Peko-peko.",
  ui_story_31780401_120_dialog_content = "Peko! Peko-peko!",
  ui_story_31780401_121_dialog_content = "Wow! Vic can speak Peko!",
  ui_story_31780401_122_dialog_content = "And this Peko seems so happy—it even came up to him and rubbed against his hands!",
  ui_story_31780401_123_dialog_content = "Th-This is...",
  ui_story_31780401_124_dialog_content = "If you couldn't even get this far in ten days, I guess you still have a lot to learn.",
  ui_story_31780401_125_dialog_content = "It is easier to communicate with wondrous beasts than it is with ordinary animals because they have minds of their own.",
  ui_story_31780401_126_dialog_content = "It's easy to gain their trust as long as you master the art of communicating with them.",
  ui_story_31780401_127_dialog_content = "...",
  ui_story_31780401_128_dialog_content = "Young man, just who are you?",
  ui_story_31780401_129_dialog_content = "Me? The name's Vic.",
  ui_story_31780401_130_dialog_content = "Vic? Why does that sound so familiar?",
  ui_story_31780401_131_dialog_content = "Wait, don't tell me you're...?",
  ui_story_31780401_132_dialog_content = "Are you the author of the book \"1,001 Fantastical Creatures\"? That famous extrozoologist?",
  ui_story_31780401_133_dialog_content = "Yeah, yeah, that's me.",
  ui_story_31780401_134_dialog_content = "I didn't realize I was in the presence of a true master.",
  ui_story_31780401_135_dialog_content = "Someone who can communicate with wondrous beasts at such a young age!",
  ui_story_31780401_136_dialog_content = "Well, don't feel too bad.",
  ui_story_31780401_137_dialog_content = "You're not much older than me.",
  ui_story_31780401_138_dialog_content = "...",
  ui_story_31780401_139_dialog_content = "Not too sure what you're talking about, but... anyway, I'll think of a way to take care of the issue of you letting one of the rabbits go.",
  ui_story_31780401_140_dialog_content = "As long as you're willing to teach me how to communicate with wondrous beasts.",
  ui_story_31780401_141_dialog_content = "No problem.",
  ui_story_31780401_142_dialog_content = "You can find me at the animal clinic in Umbraton most days.",
  ui_story_31780401_143_dialog_content = "Then it's a deal. I'll come to visit you in the future.",
  ui_story_31780401_144_dialog_content = "I still need to make my way to Lumopolis today, so I'll take my leave.",
  ui_story_31780401_145_dialog_content = "Wow, that old guy was so superficial. His attitude completely changed as soon as he found out who you were!",
  ui_story_31780401_146_dialog_content = "Don't you have a problem with him taking that other Peko back to the noble?",
  ui_story_31780401_147_dialog_content = "What else can we do? Pekos don't come cheap.",
  ui_story_31780401_148_dialog_content = "I already let one go. That's technically enough for me to wind up in Lumopolis Prison for a year.",
  ui_story_31780401_149_dialog_content = "Hmm... Good point.",
  ui_story_31780401_150_dialog_content = "But why did you tame that Peko for him, Vic?",
  ui_story_31780401_151_dialog_content = "Just imagining him taking credit for your work makes my blood boil...",
  ui_story_31780401_152_dialog_content = "I don't give a Peko's behind about that old man.",
  ui_story_31780401_153_dialog_content = "But if that Peko bites someone again, it'll be put down for sure.",
  ui_story_31780401_154_dialog_content = "It was inevitable if I hadn't intervened, considering how it looked.",
  ui_story_31780401_155_dialog_content = "I see!",
  ui_story_31780401_156_dialog_content = "You tamed the Peko to make sure it would survive.",
  ui_story_31780401_157_dialog_content = "I have to say, Vic, you really impressed me today!",
  ui_story_31780401_158_dialog_content = "By the way, I never knew you worked at an animal clinic.",
  ui_story_31780401_159_dialog_content = "Hah, you really can be quite naive sometimes.",
  ui_story_31780401_160_dialog_content = "Eh?",
  ui_story_31780401_161_dialog_content = "That was just a little fib—I don't want to see that guy ever again.",
  ui_story_31780401_162_dialog_content = "I already have my hands full with Fia and Shira. I couldn't bear to have another apprentice like him dragging me down.",
  ui_story_31780401_163_dialog_content = "PlayerName, you're still too young to fully understand the ways of the world...",
  ui_story_31780401_164_dialog_content = "... I suppose I am.",
  ui_story_31780601_1_dialog_content = "<color=#e8d9bb>Grumble...</color>",
  ui_story_31780601_2_dialog_content = "Hey, what's that sound? Are you picking anything up with those special senses of yours?",
  ui_story_31780601_3_dialog_content = "That's the sound of my stomach rumbling!",
  ui_story_31780601_4_dialog_content = "I'm starving too... We've already finished off all the dry rations we brought along with us.",
  ui_story_31780601_5_dialog_content = "And you're still hungry?! I can't believe you ate all the rations by yourself!",
  ui_story_31780601_6_dialog_content = "Huh? And when do you allege I did that? Hic—",
  ui_story_31780601_7_dialog_content = "When I was busy trying to detect the treasure!",
  ui_story_31780601_8_dialog_content = "Heheh, so you saw me, eh? Strange... I even waited until your back was turned.",
  ui_story_31780601_9_dialog_content = "Do you have any idea how loud your chewing is?!",
  ui_story_31780601_10_dialog_content = "Well, I've been trying to keep you motivated all this time, kid. It's exhausting!",
  ui_story_31780601_11_dialog_content = "Huh? I haven't heard a word of motivation from you yet!",
  ui_story_31780601_12_dialog_content = "I've been cheering you on... in my heart.",
  ui_story_31780601_13_dialog_content = "... If I could go back in time, there's no way I'd choose to go to sea with you, Vic.",
  ui_story_31780601_14_dialog_content = "<color=#e8d9bb>A few hours earlier...</color>",
  ui_story_31780601_15_dialog_content = "Oh, isn't that Vic and Shira up ahead? It's been a while since we've hung out. I should probably go over and say hello.",
  ui_story_31780601_16_dialog_content = "—I'm not really in the mood.",
  ui_story_31780601_17_dialog_content = "It's the treasure of a lifetime! Once we get our hands on it, everyone gets an equal share—and that means you too, my little one!",
  ui_story_31780601_18_dialog_content = "Well... have a safe trip.",
  ui_story_31780601_19_dialog_content = "Don't you care about your master at all? Just think about me on those treacherous seas all alone—the peril, the horror! And what if a sea monster attacks? I need you there to help me take care of this kind of thing!",
  ui_story_31780601_20_dialog_content = "Of course. That's all the more reason you should go on your own.",
  ui_story_31780601_21_dialog_content = "You two really do have one weird relationship for a master and disciple...",
  ui_story_31780601_22_dialog_content = "PlayerName! Brilliant! Let's hit the high seas together!",
  ui_story_31780601_23_dialog_content = "Hit the what now?",
  ui_story_31780601_24_dialog_content = "The high seas, my boy! You must've heard the rumors? The Pirate King's lost treasure has resurfaced once again!",
  ui_story_31780601_25_dialog_content = "The almighty Pirate King plundered innumerable treasures in his time and hid them in a mysterious location that only the bravest and most intelligent explorers could find.",
  ui_story_31780601_26_dialog_content = "This sounds like a story from one of Fia's picture books...",
  ui_story_31780601_27_dialog_content = "A reliable source has informed me that this cache of golden treasures lies deep beneath the ocean waves!",
  ui_story_31780601_28_dialog_content = "I'm not so sure about that, I mean, I know what your definition of reliable is...",
  ui_story_31780601_29_dialog_content = "I'm just a lonely old man trying to raise two adorable apprentices all alone—my legs are gray, my ears are gnarled, my eyes are old and bent.",
  ui_story_31780601_30_dialog_content = "You've been lazy all the time! Fia and I are the ones taking care of YOU!",
  ui_story_31780601_31_dialog_content = "Ahem, well, now that I've finally got the skinny on the treasure, I'm ready to face a gauntlet of pirate booby traps if I have to, all to earn a little milk money for my darling child, Fia!",
  ui_story_31780601_32_dialog_content = "Fia's not a little milk-drinking baby anymore.",
  ui_story_31780601_33_dialog_content = "PlayerName, surely you can understand, having to take care of such a huge Colossus and all. It's like having a hole in your pocket, and I've got two of 'em!",
  ui_story_31780601_34_dialog_content = "Well, now that you mention it... I actually wanted to spruce up the Colossus recently, but I couldn't raise the funds to make it happen...",
  ui_story_31780601_35_dialog_content = "But with your unique psychic abilities, we're sure to find the treasure in no time at all! Golden booty, here we come!",
  ui_story_31780601_36_option_content = "Show me the booty!",
  ui_story_31780601_37_dialog_content = "Shira, you wait here—we'll be back with the goods before you know it!",
  ui_story_31780601_38_option_content = "Can I keep all the treasure for myself?",
  ui_story_31780601_39_dialog_content = "Just what I'd expect from a Caelestite—you sniffed out the genuine aroma of my heart's sincerest intentions.",
  ui_story_31780601_40_dialog_content = "...",
  ui_story_31780601_41_dialog_content = "Yawn... Just make sure you come back alive.",
  ui_story_31780601_42_dialog_content = "According to my source, the treasure should be located in this area of the sea. Are you telling me you really can't sense anything here at all?",
  ui_story_31780601_43_dialog_content = "Nope, nothing. Maybe this area's too big or deep... maybe my psychic abilities are just too weak, or maybe... the treasure simply doesn't exist.",
  ui_story_31780601_44_dialog_content = "I'm starving... and I'm dying of thirst here... Let's just go back...",
  ui_story_31780601_45_dialog_content = "Look! There's a light shining in the water!",
  ui_story_31780601_46_dialog_content = "The light's flowing toward us. Are those... jellyfish?",
  ui_story_31780601_47_dialog_content = "I didn't think we'd run into this kind of jellyfish here.",
  ui_story_31780601_48_dialog_content = "Is this some kind of rare species? The light they're giving off seems so different from anything I've ever seen before.",
  ui_story_31780601_49_dialog_content = "Indeed, they're no ordinary jellyfish. In fact, these miraculous creatures may even lead us to the treasure!",
  ui_story_31780601_50_dialog_content = "Look, it's almost as if they're popping their heads out of the water to say hi.",
  ui_story_31780601_51_dialog_content = "Hey, you cute little jellyfish! How are you today?",
  ui_story_31780601_52_dialog_content = "Careful now! These jellyfish are venomous! Just one touch and—",
  ui_story_31780601_53_dialog_content = "It's so soft... so smooth... so... urgh...",
  ui_story_31780601_54_dialog_content = "Hey, why did you touch it?!",
  ui_story_31780601_55_dialog_content = "...",
  ui_story_31780601_56_dialog_content = "...",
  ui_story_31780601_57_dialog_content = "PlayerName... Wake up, PlayerName.",
  ui_story_31780601_58_dialog_content = "Urgh... What happened?",
  ui_story_31780601_59_dialog_content = "You passed out from a jellyfish sting, then the jellyfish school dragged our raft here.",
  ui_story_31780601_60_dialog_content = "It's so dark here. Where are we?",
  ui_story_31780601_61_dialog_content = "It seems to be a secret cave of some sort. I believe this may be where the treasure is hidden!",
  ui_story_31780601_62_dialog_content = "I can't see any treasure around here, but I can most definitively feel a dangerous presence all around us.",
  ui_story_31780601_63_dialog_content = "As long as I'm here, you can laugh in the face of danger.",
  ui_story_31780601_64_dialog_content = "If we really have nothing to fear, why are you hiding behind me?",
  ui_story_31780601_65_dialog_content = "Well, that's because it's just not very safe here, is it now?",
  ui_story_31780601_66_dialog_content = "...",
  ui_story_31780601_67_dialog_content = "Heheh, just kidding. You'll be safe—safe in the capable hands of a fearless extrozoologist extraordinaire!",
  ui_story_31780601_68_dialog_content = "All I need to do is summon my wondrous beasts, and whatever fiendish fiends we may face, we'll never have to fear, not even for a second!",
  ui_story_31780601_69_dialog_content = "Where are your wondrous beast buddies though? Why haven't you summoned them already?",
  ui_story_31780601_70_dialog_content = "Ah, well, the signal here's not so good...",
  ui_story_31780601_71_dialog_content = "Kree—Kree—!",
  ui_story_31780601_72_dialog_content = "Ah! What's that sound? The whole cave's shaking!",
  ui_story_31780601_73_dialog_content = "I've got a bad feeling about this. There must be a terrible monster waiting for us up ahead!",
  ui_story_31780601_74_dialog_content = "I don't need psychic abilities to know we need to get out of here on the double!",
  ui_story_31780601_75_dialog_content = "Hold up. A monster like that wouldn't turn up for no good reason! We must be getting close to the treasure!",
  ui_story_31780601_76_dialog_content = "You're seriously still thinking about treasure when your life's on the line?",
  ui_story_31780601_77_dialog_content = "Like I said, you don't have to worry about a thing as long as I'm around.",
  ui_story_31780601_78_dialog_content = "Lutumi Owl!",
  ui_story_31780601_79_dialog_content = "Hoot—hoot-hoot!",
  ui_story_31780601_80_dialog_content = "Bica!",
  ui_story_31780601_81_dialog_content = "Hai-hai!",
  ui_story_31780601_82_dialog_content = "Little Furball!",
  ui_story_31780601_83_dialog_content = "Chirrrrp—!",
  ui_story_31780601_84_dialog_content = "Transform!",
  ui_story_31780601_85_dialog_content = "Chirrrrp—!",
  ui_story_31780601_86_dialog_content = "Woah... They actually came!",
  ui_story_31780601_87_dialog_content = "Just stay behind me, and don't be afraid—I'll protect you!",
  ui_story_31780601_88_dialog_content = "(Weird. Why does he seem so intense all of a sudden?)",
  ui_story_31780601_89_dialog_content = "Keep moving forward—the treasure's dead ahead!",
  ui_story_31780601_90_dialog_content = "Hey, what's that shiny stuff on the ground?",
  ui_story_31780601_91_dialog_content = "Gold! It's gold!",
  ui_story_31780601_92_dialog_content = "That massive sea of golden light shining up ahead... Do you see it?!",
  ui_story_31780601_93_dialog_content = "It's the treasure! Let's go get it!",
  ui_story_31780601_94_dialog_content = "Kree! Kree—!",
  ui_story_31780601_95_dialog_content = "Ahhhhh!!!",
  ui_story_31780601_96_dialog_content = "Ouroboros?!",
  ui_story_31780601_97_dialog_content = "Didn't it fly off with Eulogoz? What's it doing here?",
  ui_story_31780601_98_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_99_dialog_content = "Woah!",
  ui_story_31780601_100_dialog_content = "Watch out!",
  ui_story_31780601_101_dialog_content = "Ouroboros took my gold coin!",
  ui_story_31780601_102_dialog_content = "It's guarding this treasure.",
  ui_story_31780601_103_dialog_content = "Strange, I've never heard anything about the Ouroboros having a penchant for hoarding gold.",
  ui_story_31780601_104_dialog_content = "It looks like we'll need to defeat it before we can claim the treasure.",
  ui_story_31780601_105_dialog_content = "Defeat the Ouroboros? How are we gonna do that?",
  ui_story_31780601_106_dialog_content = "Say no more, the Ouroboros has calmed down slightly... We just need to seize the right moment...",
  ui_story_31780601_107_dialog_content = "Don't even think about hurting it. I remember the Ouroboros being a gentle, kind creature. I don't think it'll attack us.",
  ui_story_31780601_108_dialog_content = "Maybe the treasure has corrupted its mind and turned into a greedy treasure-snatching fiend...",
  ui_story_31780601_109_dialog_content = "Kree, kree!",
  ui_story_31780601_110_dialog_content = "Lutumi Owl, Bica, Big Furball—take it down!",
  ui_story_31780601_111_dialog_content = "...",
  ui_story_31780601_112_dialog_content = "...",
  ui_story_31780601_113_dialog_content = "...",
  ui_story_31780601_114_dialog_content = "Hey! Don't you dare!",
  ui_story_31780601_115_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_116_dialog_content = "Hey now, calm down, calm down... We're not here to steal your gold, friendo, we're just here to take a look... Hey, perhaps we can even become best buddies? What do you say?",
  ui_story_31780601_117_dialog_content = "Kree, kree?",
  ui_story_31780601_118_dialog_content = "Just trust me! I AM the pre-eminent extrozoologist of the entire continent—communicating with Ouroboros is one of my myriad fortes.",
  ui_story_31780601_119_dialog_content = "Kree—",
  ui_story_31780601_120_dialog_content = "Come on, let me give you a hug.",
  ui_story_31780601_121_dialog_content = "Vic, what do you think you're doing?",
  ui_story_31780601_122_dialog_content = "Watch closely! I'm about to use my top-secret Ouroboros Charmer skills—",
  ui_story_31780601_123_dialog_content = "The first movement is the Face Pincher Stance, where one uses both hands to caress the cheek, making it warm to one instantly!",
  ui_story_31780601_124_dialog_content = "The second movement is the Tiptoe Saunter, where you stand on your tiptoes and walk back and forth on its back, casting even the wariest Ouroboros into a state of relaxation!",
  ui_story_31780601_125_dialog_content = "It's not often to see you take anything this seriously. I guess when treasure's involved, you really do have a reliable side.",
  ui_story_31780601_126_dialog_content = "Kree, kree, kree!",
  ui_story_31780601_127_dialog_content = "See how the Ouroboros' eyes have narrowed? That means it's starting to feel extremely comfortable.",
  ui_story_31780601_128_dialog_content = "Kree!",
  ui_story_31780601_129_dialog_content = "Hey?! How did it manage to turn itself into an egg?",
  ui_story_31780601_130_dialog_content = "Maybe it felt so comfortable that it fell asleep?",
  ui_story_31780601_131_dialog_content = "So... all this gold is ours now?",
  ui_story_31780601_132_dialog_content = "That's right, you can pack it up and carry it out of here.",
  ui_story_31780601_133_dialog_content = "Wahahahaha! I've finally got enough money to fix up the Colossus! There's enough here to line Soroz's entire interior with gold!",
  ui_story_31780601_134_dialog_content = "Oh, my. Where should I start the renovations? The Bridge? The Generators? Maybe I should build an extension on my room?",
  ui_story_31780601_135_dialog_content = "You know I'm not the kind of guy who likes to splurge, but it wouldn't hurt just to make my room a little more comfortable, would it?",
  ui_story_31780601_136_dialog_content = "Wipe your mouth, you're drooling.",
  ui_story_31780601_137_dialog_content = "Heheheh, sorry, I guess I got a bit overexcited!",
  ui_story_31780601_138_dialog_content = "Huh? Why aren't you picking up the gold? You've been standing there staring at it like you don't want it.",
  ui_story_31780601_139_dialog_content = "I think it's about time for you to wake up now.",
  ui_story_31780601_140_dialog_content = "Huh? What are you talking about?",
  ui_story_31780601_141_dialog_content = "I'm saying... none of this is real... this is all an illusion...",
  ui_story_31780601_142_dialog_content = "Err... My head hurts...",
  ui_story_31780601_143_dialog_content = "Pfffff! What's all this grass doing in my mouth?!",
  ui_story_31780601_144_dialog_content = "That's the herb that saved your life, my boy! Wipe your mouth now, all the medicine's getting out.",
  ui_story_31780601_145_dialog_content = "Urgh... I... Where am I?",
  ui_story_31780601_146_dialog_content = "You're on the raft, of course! Where else would you be?",
  ui_story_31780601_147_dialog_content = "The raft? What raft?",
  ui_story_31780601_148_dialog_content = "The wooden thing we're floating along on right now! Have you lost your memory?",
  ui_story_31780601_149_dialog_content = "N-No... I remember... I remember we were carried to a cave by jellyfish...",
  ui_story_31780601_150_dialog_content = "Oh, the jellyfish are still here.",
  ui_story_31780601_151_dialog_content = "This cave you mentioned was full of gold, and guarded by the Ouroboros, correct?",
  ui_story_31780601_152_dialog_content = "Yes! You were there too!",
  ui_story_31780601_153_dialog_content = "I've never been to the place, but you kept shouting—",
  ui_story_31780601_154_dialog_content = "You said you were going to carry off all the treasure and line Soroz's entire interior with gold. And something about building an extension on your room. It certainly sounded like a wonderful dream.",
  ui_story_31780601_155_dialog_content = "A dream? It couldn't have all been a dream!",
  ui_story_31780601_156_dialog_content = "It's all because of the jellyfish—the Dreamweaver Jellyfish. It has the ability to read the thoughts and emotions of whoever touches it.",
  ui_story_31780601_157_dialog_content = "They possess the power to create the most perfect or most horrendous visions in the minds of the affected, based on their innermost fears and desires.",
  ui_story_31780601_158_dialog_content = "So... So my innermost desire is... for gold?",
  ui_story_31780601_159_dialog_content = "That's right! As the last Caelestite, all you can think of is gold, not a single grand ambition or lofty ideal in sight!",
  ui_story_31780601_160_dialog_content = "Erm... Well... I just...",
  ui_story_31780601_161_dialog_content = "Heehee! It's just the two of us here, you don't need to explain yourself to me.",
  ui_story_31780601_162_dialog_content = "I totally understand you. If I had touched that thing, I probably would've had the very same dream!",
  ui_story_31780601_163_dialog_content = "That's not it. I'm not a greedy person. That dream must've been some kind of brain burp!",
  ui_story_31780601_164_dialog_content = "Why else would you risk life and limb to come along with me on this rickety raft?",
  ui_story_31780601_165_dialog_content = "I was worried that it might be too dangerous for you to sail off all alone!",
  ui_story_31780601_166_dialog_content = "So, would you still have come with me if there were no treasure to be had?",
  ui_story_31780601_167_option_content = "I don't think so.",
  ui_story_31780601_168_dialog_content = "(Sigh) So the Pirate King's treasure really was a mere legend after all... Well, that's the last time I go believing everything I read in Fia's picture books!",
  ui_story_31780601_169_dialog_content = "You got all this from a kids' storybook?!",
  ui_story_31780601_170_dialog_content = "By the way, I have absolutely no idea which direction we're drifting in right now.",
  ui_story_31780601_171_dialog_content = "I was doing everything I could to save you, so naturally I lost track of where the tide was taking us.",
  ui_story_31780601_172_dialog_content = "We need to think of a way to get back home.",
  ui_story_31780601_173_dialog_content = "Any ideas?",
  ui_story_31780601_174_dialog_content = "Well, there's always the most primitive yet most effective method—",
  ui_story_31780601_175_dialog_content = "Help!!!"
}
return config
